/**
 * ニュージーランドのクイズ(102問)。
 *
 * 難易度は1〜10で、基準は他の盤面と同じく「その国の外にいる一般的な人が
 * どれくらい答えられそうか」。
 *   1〜3 … 来たことがなくても常識で解ける
 *   4〜6 … 旅行したり少し調べたことがあれば分かる
 *   7〜8 … 理由が土地に結びついていて、踏み込んだ知識が要る
 *   9〜10 … 現地の人か、強い関心のある人でないと難しい
 *
 * ## 都市カードとの重なりについて
 *
 * 都市カード(43件)が扱う具体的な事実(ワイタンギ条約の英語版とマオリ語版の
 * 食い違い・カイコウラの隆起量・タカヘの再発見・ホビットン・ハンギ調理など)は
 * ここでは問わない。代わりに、国全体の歴史・政治・言語・スポーツ・通貨・
 * 生き物など、**都市カードが直接は触れていない主題**を選んである。
 *
 * ```
 * node scripts/check-quiz.mjs newzealand
 * ```
 * で、答えの漏れ・4言語の混入と欠け・正解の位置の偏り・題材の偏りを確認すること。
 *
 * ## 確度について
 *
 * 難易度9〜10の年号・固有名詞は1問ずつ裏を取った。特に確度が低いと
 * 判断したもの(投票年齢18歳への引き下げ年)は報告に書く。
 *
 * 選択肢は3つ。正解の位置(`a`)は 0/1/2 がほぼ同数になるよう散らしてある。
 */
function t(source) {
  const parts = source.split("|");
  if (parts.length !== 4) {
    throw new Error(`4言語(en|es|fr|ja)で書いてください: ${source.slice(0, 60)}…`);
  }
  const [en, es, fr, ja] = parts;
  return { en, es, fr, ja };
}

/** 1問を組み立てる。`o` は選択肢の配列、`a` は正解の添字。 */
function q(difficulty, question, options, a, fact) {
  return { difficulty, q: t(question), o: options.map(t), a, f: t(fact) };
}

